# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AÇIK DAVETİN BAŞLAMASI VE SAFA TEPESİ HUTBESİ (613)</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İlahi Emirler (Şuarâ 214 &amp; Hicr 94)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• 3 yıl süren gizli davet döneminin ardından:</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">1. «Önce en yakın akrabalarını uyar!»</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11" fill="#334155">(Şuarâ suresi, 214. ayet ➔ Akraba daveti)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">2. «Sana emredileni açıkça ortaya koy!»</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11" fill="#334155">(Hicr suresi, 94. ayet ➔ Genel açık davet)</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Davet bütün Mekke halkına ilan edilmiştir.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Safa Tepesi ve Muhammedü\'l-Emin</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• «Şu dağın arkasında düşman ordusu var</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11.5" fill="#14532d">desem bana inanır mısınız?»</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">• Mekkeliler: «Evet! Senin yalan söylediğini</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">şimdiye kadar duymadık.»</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11" fill="#334155">• Ebû Leheb\'in sert tepkisi üzerine</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Tebbet (Mesed) Suresi indirilmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MÜŞRİKLERİN TEPKİLERİ, HABEŞİSTAN HİCRETİ VE BOYKOT</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Müşriklerin Tepki Nedenleri</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#7f1d1d">• Putperestlik ve atalar dinine</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#7f1d1d">körü körüne bağlılık</text>\n  <text x="125" y="140" text-anchor="middle" font-size="11" fill="#7f1d1d">• Mekke\'deki siyasi ve ekonomik</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" fill="#7f1d1d">çıkarlarını kaybetme korkusu</text>\n  <text x="125" y="182" text-anchor="middle" font-size="11" fill="#7f1d1d">• Köle ile efendiyi eşit gören</text>\n  <text x="125" y="200" text-anchor="middle" font-size="11" fill="#7f1d1d">adalet ilkesine kibirle karşı çıkma</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Habeşistan Hicreti (615-616)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#713f12">• İslam\'da İLK HİCRET hareketidir.</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#713f12">• Habeş Kralı Necaşi Ashame</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">kimseye zulmedilmeyen adil bir</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">hükümdar olduğu için seçilmiştir.</text>\n  <text x="350" y="182" text-anchor="middle" font-size="11" fill="#713f12">• Cafer bin Ebû Tâlib, Necaşi\'nin</text>\n  <text x="350" y="200" text-anchor="middle" font-size="11" fill="#713f12">huzurunda Meryem suresini okudu.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Boykot Yılları (616-619)</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#581c87">• Haşimoğulları mahallesinde</text>\n  <text x="575" y="116" text-anchor="middle" font-size="11" fill="#581c87">(Şi\'b-i Ebî Tâlib) 3 yıl kuşatma</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" fill="#581c87">• Alışveriş, evlilik ve konuşma</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#581c87">yasağı içeren ağır ambargo</text>\n  <text x="575" y="182" text-anchor="middle" font-size="11" fill="#581c87">• Hz. Hatice ve Ebû Tâlib\'in</text>\n  <text x="575" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">vefatı ➔ Hüzün Yılı (Senetü\'l-Hüzün)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN SABIR, KARARLILIK VE MERHAMET ÖRNEKLİĞİ</text>\n  <rect x="25" y="48" width="650" height="85" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Tarihî Kararlılık Sözü (Güneş ve Ay Misali)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">«Ey amca! Allah\'a yemin ederim ki güneşi sağ elime, ayı da sol elime verseler yine de bu davadan</text>\n  <text x="350" y="116" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">vazgeçmem! Ya Allah bu dini hâkim kılar ya da ben bu uğurda canımı veririm.»</text>\n\n  <rect x="25" y="145" width="310" height="95" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="168" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Sahabilerin Sabır ve Direnişi</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11" fill="#155e75">• Bilâl-i Habeşî («Ehad! Ehad!» - Allah birdir!)</text>\n  <text x="180" y="210" text-anchor="middle" font-size="11" fill="#155e75">• Ammâr bin Yâsir ailesi (Hz. Sümeyye ve Yâsir)</text>\n  <text x="180" y="228" text-anchor="middle" font-size="11" fill="#155e75">• Mus\'ab bin Umeyr ve Suheyb-i Rûmî</text>\n\n  <rect x="365" y="145" width="310" height="95" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="168" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tâif Yolculuğu ve Affedicilik</text>\n  <text x="520" y="192" text-anchor="middle" font-size="11" fill="#14532d">• Tâif\'te taşlanmasına rağmen beddua etmedi:</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">«Rabbim! Kavmimi bağışla, çünkü onlar</text>\n  <text x="520" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">gerçeği bilmiyorlar.» diyerek dua etti.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
